export const getExportControlReportUrl = (companyId: string,
    format: 'pdf' | 'xlsx',
    params?: ExportControlReportParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/control/${companyId}/reports/${format}?${stringifiedParams}` : `/api/control/${companyId}/reports/${format}`
}

